package com.banamex.transferlimits.api.dto;

import com.banamex.transferlimits.domain.Channel;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Positive;
import java.math.BigDecimal;
import java.util.UUID;

/**
 * {@code TransferValidationRequest} schema.
 *
 * @param transferId idempotency key generated by the client
 * @param channel origination channel
 * @param amount amount to transfer ({@code > 0}, at most 2 decimals)
 * @param currency ISO 4217 currency, only MXN
 */
public record TransferValidationRequest(
    @NotNull(message = ApiConstraints.NOT_NULL) UUID transferId,
    @NotNull(message = ApiConstraints.NOT_NULL) Channel channel,
    @NotNull(message = ApiConstraints.NOT_NULL)
        @Positive(message = ApiConstraints.AMOUNT_POSITIVE)
        @Digits(
            integer = ApiConstraints.AMOUNT_INTEGER_DIGITS,
            fraction = ApiConstraints.AMOUNT_FRACTION_DIGITS,
            message = ApiConstraints.AMOUNT_DIGITS)
        BigDecimal amount,
    @NotNull(message = ApiConstraints.NOT_NULL)
        @Pattern(
            regexp = ApiConstraints.CURRENCY_PATTERN,
            message = ApiConstraints.CURRENCY_INVALID)
        String currency) {}
